const payloadSchema = z
  .object({
    fiscalYearId: z.string().trim().min(1).optional(),
    /** Motivo para cerrar con comprobaciones pendientes (queda en la auditoría). */
    overrideReason: z.string().trim().max(500).optional(),
  })
  .nullable()

const payloadSchema = z.object({
  confirm: z.literal(true),
  reason: z.string().trim().min(5).max(500),
})

const payloadSchema = z.object({
  accounts: z.array(accountSchema).optional(),
  journals: z.array(journalSchema).optional(),
})

const accountSchema = z.object({
  code: z.string().trim().min(1),
  name: z.string().trim().min(1),
  type: z.enum(["ASSET", "LIABILITY", "EQUITY", "REVENUE", "EXPENSE", "MIXED"]),
  parentCode: z.string().trim().nullable().optional(),
  level: z.number().int().positive().optional(),
  isPostable: z.boolean().optional(),
  isActive: z.boolean().optional(),
  source: z.string().trim().optional(),
  templateVersion: z.string().trim().nullable().optional(),
})

const journalSchema = z.object({
  code: z.string().trim().min(1),
  name: z.string().trim().min(1),
})

const authSignInSchema = z.object({
  email: z.string().trim().email("Debes indicar un email válido."),
  password: z.string().min(8, "La contraseña debe tener al menos 8 caracteres."),
})

const authSignUpSchema = authSignInSchema.extend({
  name: z.string().trim().min(2, "El nombre debe tener al menos 2 caracteres.").max(100, "El nombre no puede superar 100 caracteres."),
})

const authSignInSchema = z.object({
  email: z.string().trim().email("Debes indicar un email válido."),
  password: z.string().min(8, "La contraseña debe tener al menos 8 caracteres."),
})

const payloadSchema = z.object({
  token: z.string().trim().min(20).max(1024),
  password: z.string().min(8, "La contraseña debe tener al menos 8 caracteres.").max(256),
})

const payloadSchema = z
  .object({
    tenantId: z.string().trim().min(1).optional(),
    companyId: z.string().trim().min(1).optional(),
    fiscalYearId: z.string().trim().min(1).optional(),
  })
  .refine((value) => Boolean(value.tenantId) || (Boolean(value.companyId) && Boolean(value.fiscalYearId)), {
    message: "Indica el espacio o la empresa y el ejercicio.",
  })
  .refine((value) => Boolean(value.companyId) === Boolean(value.fiscalYearId), {
    message: "Empresa y ejercicio deben indicarse juntos.",
  })

const createCustomerSchema = z.object({
  name: z.string().trim().min(2, "El nombre debe tener al menos 2 caracteres."),
  taxId: z.string().trim().min(1, "Debes indicar CIF/NIF/VAT."),
  address: z.string().trim().min(1, "Debes indicar la dirección fiscal."),
  addressLine2: z.string().trim().optional().or(z.literal("")),
  postalCode: z.string().trim().min(1, "Debes indicar el código postal."),
  city: z.string().trim().min(1, "Debes indicar la ciudad."),
  province: z.string().trim().min(1, "Debes indicar la provincia."),
  countryCode: z.string().trim().length(2, "El país debe ser un código ISO de 2 letras."),
  email: z
    .string()
    .trim()
    .email("Debes indicar un email válido.")
    .optional()
    .or(z.literal("")),
  phone: z.string().trim().optional().or(z.literal("")),
}).superRefine((value, ctx) => {
  const taxIdProblem = value.countryCode.toUpperCase() === "ES" ? describeSpanishTaxIdProblem(value.taxId) : null;
  if (taxIdProblem) {
    ctx.addIssue({ code: "custom", message: taxIdProblem, path: ["taxId"] });
  }
})

const moveSchema = z.object({
  stageId: z.string().trim().min(1),
  index: z.number().int().min(0).optional(),
  lostReason: optionalText(500),
})

const stagesSchema = z.object({
  stages: z.array(z.object({
    id: z.string().trim().optional(),
    name: z.string().trim().min(1).max(60),
    probability: z.number().int().min(0).max(100),
    kind: z.enum(CRM_STAGE_KINDS),
  })).min(3).max(20),
})

const updateSchema = z.object({
  name: z.string().trim().min(1, "Indica el nombre del grupo.").max(80, "El nombre no puede superar 80 caracteres.").optional(),
  priceListId: z.string().trim().nullable().optional(),
  discountPct: z.number().min(0, "El descuento debe estar entre 0 y 100 %.").max(100, "El descuento debe estar entre 0 y 100 %.").optional(),
})

const createSchema = z.object({
  code: z.string().trim().min(1, "Indica un código corto (por ejemplo, DIST).").max(12, "El código no puede superar 12 caracteres."),
  name: z.string().trim().min(1, "Indica el nombre del grupo.").max(80, "El nombre no puede superar 80 caracteres."),
  priceListId: z.string().trim().nullable().optional(),
  discountPct: z.number().min(0, "El descuento debe estar entre 0 y 100 %.").max(100, "El descuento debe estar entre 0 y 100 %.").optional(),
})

const createPayloadSchema = z.object({
  type: z.enum(documentTypes),
  code: z.string().trim().min(1, "Indica un código corto (por ejemplo, T).").max(10, "El código no puede superar 10 caracteres."),
  name: nameSchema,
  prefix: prefixSchema,
  format: formatSchema.optional(),
  nextNumber: z.number().int().positive().optional(),
  isDefault: z.boolean().optional(),
  ...gapSchema,
})

const nameSchema = z.string().trim().min(1, "Indica el nombre de la serie (por ejemplo, Tickets).").max(60, "El nombre no puede superar 60 caracteres.")

const prefixSchema = z.string().trim().min(1, "Indica el prefijo (por ejemplo, FA).").max(20, "El prefijo no puede superar 20 caracteres.")

const formatSchema = z.string().trim().min(1, "Indica el formato.").max(80, "El formato no puede superar 80 caracteres.")

const gapSchema = {
  /** Confirmación explícita para saltar números (deja huecos): exige motivo y queda auditado. */
  confirmGap: z.boolean().optional(),
  gapReason: z.string().trim().max(500).optional(),
}

const legacyPayloadSchema = z.object({
  type: z.enum(documentTypes),
  prefix: prefixSchema,
  format: formatSchema.optional(),
  nextNumber: z.number().int().positive().optional(),
  ...gapSchema,
})

const prefixSchema = z.string().trim().min(1, "Indica el prefijo (por ejemplo, FA).").max(20, "El prefijo no puede superar 20 caracteres.")

const formatSchema = z.string().trim().min(1, "Indica el formato.").max(80, "El formato no puede superar 80 caracteres.")

const gapSchema = {
  /** Confirmación explícita para saltar números (deja huecos): exige motivo y queda auditado. */
  confirmGap: z.boolean().optional(),
  gapReason: z.string().trim().max(500).optional(),
