const formatSchema = z.string().trim().min(1, "Indica el formato.").max(80, "El formato no puede superar 80 caracteres.")

const gapSchema = {
  /** Confirmación explícita para saltar números (deja huecos): exige motivo y queda auditado. */
  confirmGap: z.boolean().optional(),
  gapReason: z.string().trim().max(500).optional(),
}

const legacyPayloadSchema = z.object({
  type: z.enum(documentTypes),
  prefix: prefixSchema,
  format: formatSchema.optional(),
  nextNumber: z.number().int().positive().optional(),
  ...gapSchema,
})

const prefixSchema = z.string().trim().min(1, "Indica el prefijo (por ejemplo, FA).").max(20, "El prefijo no puede superar 20 caracteres.")

const formatSchema = z.string().trim().min(1, "Indica el formato.").max(80, "El formato no puede superar 80 caracteres.")

const gapSchema = {
  /** Confirmación explícita para saltar números (deja huecos): exige motivo y queda auditado. */
  confirmGap: z.boolean().optional(),
  gapReason: z.string().trim().max(500).optional(),
}

const dunningOptOutSchema = z.object({
  customerId: z.string().trim().min(1),
  optOut: z.boolean(),
})

const bulkSchema = z.object({
  invoiceIds: z.array(z.string().trim().min(1)).min(1, "Selecciona al menos una factura.").max(200, "Como máximo 200 facturas por envío."),
})

const sendReminderSchema = sendInvoiceEmailSchema.extend({
  reminderLevel: z.union([z.literal(1), z.literal(2), z.literal(3)]).optional().nullable(),
})

const sendInvoiceEmailSchema = z.object({
  invoiceId: z.string().trim().min(1, "Indica la factura."),
  to: emailList,
  cc: emailList,
  subject: z.string().trim().max(250, "El asunto no puede superar 250 caracteres.").optional().nullable(),
  body: z.string().max(20_000, "El mensaje es demasiado largo.").optional().nullable(),
  copyToSelf: z.boolean().optional(),
})

const voidSchema = z.object({
  reason: z.string().trim().optional().or(z.literal("")),
})

const payloadSchema = z.object({
  filedAt: z.string().trim().regex(/^\d{4}-\d{2}-\d{2}$/),
  receiptNumber: z.string().trim().min(1).max(60),
  nrc: z.string().trim().max(60).optional().nullable(),
})

const payloadSchema = z.object({
  code: z.enum(spanishFiscalModelCodes),
  period: z.string().trim().min(4).max(7),
  status: z.enum(["DRAFT", "READY", "FILED"]),
  reopenReason: z.string().trim().min(3).max(500).optional(),
})

const payloadSchema = z.object({
  code: z.enum(spanishFiscalModelCodes),
  period: z.string().trim().min(4).max(7),
  // "Presentado" no se elige al crear: se marca después con fecha y justificante (POST /[id]/file).
  status: z.enum(["DRAFT", "READY"]).default("DRAFT"),
})

const payloadSchema = z.object({
  warehouseId: z.string().trim().min(1, "Elige el almacén."),
  countedAt: z.string().trim().min(1, "Indica la fecha del recuento."),
  notes: z.string().trim().max(500).optional().or(z.literal("")),
  lines: z
    .array(z.object({
      itemId: z.string().trim().min(1),
      countedQuantity: z.number().min(0, "Lo contado no puede ser negativo."),
      expectedQuantity: z.number(),
    }))
    .min(1, "Introduce al menos una cantidad contada.")
    .max(2000),
})

const bulkInvoiceEmailSchema = z.object({
  invoiceIds: z.array(z.string().trim().min(1)).min(1, "Selecciona al menos una factura.").max(100, "Como máximo 100 facturas por envío."),
  copyToSelf: z.boolean().optional(),
})

const invoiceEmailSettingsSchema = z.object({
  templates: z.object({
    invoice: templateSchema.optional(),
    reminder1: templateSchema.optional(),
    reminder2: templateSchema.optional(),
    reminder3: templateSchema.optional(),
  }),
  copyToSelfDefault: z.boolean(),
  dunning: z.object({
    enabled: z.boolean(),
    firstDelayDays: z.number().int().min(0, "Entre 0 y 365 días.").max(365, "Entre 0 y 365 días."),
    intervalDays: z.number().int().min(1, "Entre 1 y 365 días.").max(365, "Entre 1 y 365 días."),
    maxReminders: z.number().int().min(1, "Entre 1 y 3 recordatorios.").max(3, "Entre 1 y 3 recordatorios."),
  }),
})

const templateSchema = z.object({
  subject: z.string().max(250, "El asunto no puede superar 250 caracteres."),
  body: z.string().max(20_000, "El mensaje es demasiado largo."),
})

const payloadSchema = z.object({
  invoiceId: z.string().trim().min(1),
  amountApplied: z.number().positive(),
  postedAt: z.string().trim().min(1),
  paymentMethodId: z.string().trim().min(1),
  /** Movimiento bancario del que nace el cobro: se concilia en la misma operación. */
  bankTransactionId: z.string().trim().min(1).optional(),
})

const createCreditNoteSchema = z.object({
  reason: z.enum(RECTIFICATION_REASONS as [string, ...string[]], { error: "Indica la causa de la rectificación (R1–R5)." }),
  type: z.enum(RECTIFICATION_TYPES as [string, ...string[]]).default("DIFFERENCES"),
  /** FULL: anula íntegramente la original. PARTIAL: solo las líneas indicadas (importes a abonar). */
  scope: z.enum(["FULL", "PARTIAL"]).default("FULL"),
  description: z.string().trim().min(3, "Explica brevemente el motivo de la rectificación.").max(500, "El motivo no puede superar 500 caracteres."),
  issueDate: z.string().trim().optional().or(z.literal("")),
  /**
   * PARTIAL + DIFFERENCES: importes (positivos) que se abonan.
   * SUBSTITUTION: líneas correctas que sustituyen a las de la factura original.
   */
  lines: z.array(creditNoteLineSchema).max(200).optional(),
  /** Serie de rectificativas elegida (si la empresa tiene varias). Vacío = la serie por defecto. */
  seriesId: seriesIdSchema,
  /** false guarda la rectificativa como borrador. */
  issue: z.boolean().optional(),
}).superRefine((value, ctx) => {
  if ((value.scope === "PARTIAL" || value.type === "SUBSTITUTION") && (!value.lines || value.lines.length === 0)) {
    ctx.addIssue({ code: "custom", message: "Indica al menos una línea para la rectificación.", path: ["lines"] });
  }
})

const creditNoteLineSchema = z.object({
  itemId: z.string().trim().optional().nullable(),
  description: z.string().trim().min(1, "La línea debe tener descripción."),
  quantity: z.number().positive("La cantidad debe ser mayor que 0."),
  unitPrice: z.number().nonnegative("El importe no puede ser negativo."),
  discountPct: z.number().min(0).max(100).optional(),
  taxIds: z.array(z.uuid("El impuesto seleccionado no es válido.")).max(12).optional(),
  /** Líneas antiguas sin impuestos configurados: tipo de IVA y retención de la línea original. */
  taxRate: z.number().min(0).max(100).optional(),
  retentionRate: z.number().min(0).max(100).optional(),
})

const seriesIdSchema = z.string().trim().max(80, "La serie seleccionada no es válida.").nullable().optional()

const createCreditNoteSchema = z.object({
  reason: z.enum(RECTIFICATION_REASONS as [string, ...string[]], { error: "Indica la causa de la rectificación (R1–R5)." }),
  type: z.enum(RECTIFICATION_TYPES as [string, ...string[]]).default("DIFFERENCES"),
  /** FULL: anula íntegramente la original. PARTIAL: solo las líneas indicadas (importes a abonar). */
  scope: z.enum(["FULL", "PARTIAL"]).default("FULL"),
  description: z.string().trim().min(3, "Explica brevemente el motivo de la rectificación.").max(500, "El motivo no puede superar 500 caracteres."),
  issueDate: z.string().trim().optional().or(z.literal("")),
  /**
   * PARTIAL + DIFFERENCES: importes (positivos) que se abonan.
   * SUBSTITUTION: líneas correctas que sustituyen a las de la factura original.
   */
  lines: z.array(creditNoteLineSchema).max(200).optional(),
  /** Serie de rectificativas elegida (si la empresa tiene varias). Vacío = la serie por defecto. */
  seriesId: seriesIdSchema,
  /** false guarda la rectificativa como borrador. */
  issue: z.boolean().optional(),
}).superRefine((value, ctx) => {
