})

const updateOrderSchema = z.object({
  guests: z.number().int().min(1).max(200).optional(),
  waiterUserId: z.string().trim().nullable().optional(),
  label: z.string().trim().max(60).nullable().optional(),
})

const setMenuSchema = z.object({
  courses: z.array(z.object({
    name: z.string().trim().min(1, "Pon nombre al tiempo (Primero, Segundo…).").max(40),
    course: z.number().int().min(0).max(4),
    choices: z.array(z.object({ itemId: id, supplement: z.number().min(0).max(10_000) })).min(1).max(60),
  })).min(1).max(8),
})

const recipeSchema = z.object({
  lines: z.array(z.object({ ingredientItemId: z.string().trim().min(1), quantity: z.number().positive("Las cantidades deben ser mayores que cero.").max(100_000) })).min(1, "Añade al menos un ingrediente.").max(80),
})

const movementSchema = z.object({
  type: z.enum(["IN", "OUT"]),
  amount: z.number().positive().max(999_999_999),
  reason: z.string().trim().min(2, "Indica el motivo.").max(200),
  // Traspaso con este banco (se contabiliza); sin él, solo cuenta en el arqueo.
  bankAccountId: z.string().trim().nullable().optional(),
})

const setupSchema = z.object({
  registerId: z.string().trim().min(1).nullable().optional(),
  registerName: z.string().trim().max(60).nullable().optional(),
  areas: z.array(z.object({ name: z.string().trim().max(40), tables: z.number().int().min(0).max(100), seats: z.number().int().min(1).max(50) })).min(1).max(10),
})

const refundSchema = z.object({
  registerId: z.string().trim().min(1),
  clientRequestId: z.string().trim().min(8).max(80),
  reason: z.string().trim().max(300).nullable().optional(),
  method: z.enum(["cash", "card"]).optional(),
  // Sin líneas: se devuelve todo lo que quede del ticket.
  lines: z.array(z.object({ lineId: z.string().trim().min(1), quantity: z.number().positive() })).max(300).optional(),
})

